namespace
{
    // The same sanitization import_mojulo.py uses to survive Interchange's
    // punctuation stripping ('entity:hero' -> 'entity_hero',
    // 'gframe_mk2_multi:idle' -> 'gframe_mk2_multi_idle').
    FString CleanName(const FString& S)
    {
        FString Out;
        Out.Reserve(S.Len());
        for (const TCHAR C : S) Out.AppendChar(FChar::IsAlnum(C) ? C : TEXT('_'));
        return Out;
    }

    // A game pack imports one asset subtree PER LEVEL
    // (/Game/MojuloPack/Levels/<ref>/model/...), so a multi-level pack holds
    // N copies of every shared figure's clips under identical names.
    // Indexing the whole pack let the LAST level imported win — sequences
    // whose bindings point at another map's actors (pinned before U4; the
    // one-level slice could not see it). Scope to THIS level's subtree; a
    // world-scope pack (U0 shape, assets straight under the root) has no
    // Levels/ subtree and takes the root.
    TMap<FString, FSoftObjectPath> IndexLevelAssets(const UClass* Class, const FString& LevelRef)
    {
        const FAssetRegistryModule& Registry = FModuleManager::LoadModuleChecked<FAssetRegistryModule>(TEXT("AssetRegistry"));
        TArray<FAssetData> Assets;
        Registry.Get().GetAssetsByClass(Class->GetClassPathName(), Assets, true);
        const FString LevelRoot = FString(TEXT("/Game/MojuloPack/Levels/")) + LevelRef;
        TMap<FString, FSoftObjectPath> Scoped, PackWide;
        for (const FAssetData& Asset : Assets)
        {
            const FString Path = Asset.PackagePath.ToString();
            if (!Path.StartsWith(TEXT("/Game/MojuloPack"))) continue;
            const FString Key = CleanName(Asset.AssetName.ToString());
            PackWide.Add(Key, Asset.ToSoftObjectPath());
            if (Path == LevelRoot || Path.StartsWith(LevelRoot + TEXT("/"))) Scoped.Add(Key, Asset.ToSoftObjectPath());
        }
        return Scoped.Num() > 0 ? Scoped : PackWide;
    }
}

AMojuloMarker::AMojuloMarker()
{
    PrimaryActorTick.bCanEverTick = false;
    Mesh = CreateDefaultSubobject<UStaticMeshComponent>(TEXT("MarkerMesh"));
    RootComponent = Mesh;
    Mesh->SetMobility(EComponentMobility::Movable);
    Mesh->SetCollisionEnabled(ECollisionEnabled::NoCollision);
}

void AMojuloMarker::SetShape(bool bSphere, const FVector& WorldScale, const FLinearColor& Color)
{
    UStaticMesh* Shape = LoadObject<UStaticMesh>(nullptr, bSphere
        ? TEXT("/Engine/BasicShapes/Sphere.Sphere")
        : TEXT("/Engine/BasicShapes/Cube.Cube"));
    if (Shape != nullptr) Mesh->SetStaticMesh(Shape);
    Mesh->SetWorldScale3D(WorldScale);
    UMaterial* Base = LoadObject<UMaterial>(nullptr, TEXT("/Engine/BasicShapes/BasicShapeMaterial.BasicShapeMaterial"));
    if (Base != nullptr)
    {
        UMaterialInstanceDynamic* Mid = UMaterialInstanceDynamic::Create(Base, this);
        Mid->SetVectorParameterValue(FName(TEXT("Color")), Color);
        Mesh->SetMaterial(0, Mid);
    }
}

AMojuloGameMode::AMojuloGameMode()
{
    PrimaryActorTick.bCanEverTick = true;
    DefaultPawnClass = AMojuloWalker::StaticClass();
    HUDClass = AMojuloHUD::StaticClass();
}

void AMojuloGameMode::InitGame(const FString& MapName, const FString& Options, FString& ErrorMessage)
{
    Super::InitGame(MapName, Options, ErrorMessage);
    if (!MojuloPawnClass.IsNull())
    {
        UClass* ProjectPawn = MojuloPawnClass.TryLoadClass<APawn>();
        if (ProjectPawn != nullptr && !ProjectPawn->HasAnyClassFlags(CLASS_Abstract)) DefaultPawnClass = ProjectPawn;
        else UE_LOG(LogTemp, Warning, TEXT("[mojulo] invalid MojuloPawnClass: %s; retaining default pawn"), *MojuloPawnClass.ToString());
    }
}

void AMojuloGameMode::BeginPlay()
{
    Super::BeginPlay();
    FString Map = GetWorld()->GetMapName();
    Map.RemoveFromStart(GetWorld()->StreamingLevelsPrefix); // strips UEDPIE_N_
    LevelRef = Map;
    bScoreLoaded = MojuloScore::LoadScore(MojuloScore::ScorePathForMap(Map), Score);
    if (!bScoreLoaded)
    {
        UE_LOG(LogTemp, Error, TEXT("[mojulo] no score.json for map '%s' under %s"), *Map, *MojuloScore::PackDir());
        return;
    }
    EyeScale = FMath::Max(0.5f, Score.Eye / 1.7f);
    SpawnMechanicMarkers();
    StartMusic();
    float ShotSeconds = 0.f;
    if (FParse::Value(FCommandLine::Get(), TEXT("MojuloShot="), ShotSeconds)) ShotAt = ShotSeconds;
    float JumpSeconds = 0.f;
    if (FParse::Value(FCommandLine::Get(), TEXT("MojuloAutoJump="), JumpSeconds)) JumpAt = JumpSeconds;
}

void AMojuloGameMode::ConfigureWalker()
{
    APawn* Pawn = UGameplayStatics::GetPlayerPawn(this, 0);
    if (Pawn == nullptr) return;
    PlayerPawn = Pawn;
    Walker = Cast<AMojuloWalker>(Pawn);
    PlayerKillZ = Score.Spawn.Z - 30000.f;
    if (Score.bHasColliders) PlayerKillZ = Score.MinColliderZ * 100.f - 10000.f;
    if (Walker != nullptr) Walker->InitFromScore(Score.Eye, EyeScale, Score.Spawn, PlayerKillZ);
    // Foreign pawns keep their PlayerStart placement, dimensions, input and camera.
    PlayerSpawn = Pawn->GetActorTransform();
    bForeignAutoWalk = Walker == nullptr && FParse::Param(FCommandLine::Get(), TEXT("MojuloAutoWalk"));
    bProbePressed = false;
    ProbeStart = Pawn->GetActorLocation();
    UE_LOG(LogTemp, Display, TEXT("[mojulo] pawn_class=%s kernel_walker=%d"), *Pawn->GetClass()->GetPathName(), Walker != nullptr);
    Hp = Score.bHasHp ? Score.StartHp : -1.f;
    SurviveLeft = Score.SurviveSeconds;
    SetupLocomotion();
}

FVector AMojuloGameMode::PlayerFeet() const
{
    return PlayerPawn->GetActorLocation() - FVector(0.f, 0.f, PlayerPawn->GetSimpleCollisionHalfHeight());
}

void AMojuloGameMode::ResetPlayer()
{
    if (Walker != nullptr) Walker->Respawn();
    else if (PlayerPawn != nullptr)
    {
        if (UPawnMovementComponent* Movement = PlayerPawn->GetMovementComponent()) Movement->StopMovementImmediately();
        PlayerPawn->SetActorTransform(PlayerSpawn, false, nullptr, ETeleportType::TeleportPhysics);
    }
}

AActor* AMojuloGameMode::FindActorByCleanName(const FString& Wanted) const
{
    const FString Want = CleanName(Wanted);
    for (TActorIterator<AActor> It(GetWorld()); It; ++It)
    {
#if WITH_EDITOR
        const FString Label = It->GetActorLabel();
#else
        const FString Label = It->GetName();
#endif
        if (CleanName(Label) == Want) return *It;
    }
    return nullptr;
}

void AMojuloGameMode::SetActorTreeHidden(AActor* Root, bool bHidden)
{
    // Interchange imports one actor per GLB node — hiding the wrapper alone
    // leaves the body visible (pinned at U2: the "hidden" player seat stood
    // in every U0 screenshot). Walk the attachment tree.
    if (Root == nullptr) return;
    Root->SetActorHiddenInGame(bHidden);
    TArray<AActor*> Children;
    Root->GetAttachedActors(Children);
    for (AActor* Child : Children) SetActorTreeHidden(Child, bHidden);
}

void AMojuloGameMode::SetActorTreeCollision(AActor* Root, bool bEnabled)
{
    // The player's suit is a cosmetic FOLLOWER — its imported part colliders
    // wedge the pilot capsule at spawn (pinned at U3: WASD ran in place
    // while a persistent auto-walk force squeezed free). Blocking is the
    // score colliders' job, never the suit body's.
    if (Root == nullptr) return;
    Root->SetActorEnableCollision(bEnabled);
    TArray<AActor*> Children;
    Root->GetAttachedActors(Children);
    for (AActor* Child : Children) SetActorTreeCollision(Child, bEnabled);
}

void AMojuloGameMode::SetActorTreeMovable(AActor* Root)
{
    // Interchange imports scene actors STATIC — SetActorLocation fails
    // silently and sequences cannot pose parts (pinned at the U3 eyes gate:
    // the suit stood frozen in rest pose). Movable, whole tree.
    if (Root == nullptr) return;
    if (USceneComponent* RootComp = Root->GetRootComponent())
        RootComp->SetMobility(EComponentMobility::Movable);
    TArray<AActor*> Children;
    Root->GetAttachedActors(Children);
    for (AActor* Child : Children) SetActorTreeMovable(Child);
}

void AMojuloGameMode::BuildSequenceIndex()
{
    // the rigid figures' clips (LevelSequences) and the skinned figures' (AnimSequences), each scoped to this level
    SequenceIndex = IndexLevelAssets(ULevelSequence::StaticClass(), LevelRef);
    AnimIndex = IndexLevelAssets(UAnimSequence::StaticClass(), LevelRef);
}

ULevelSequence* AMojuloGameMode::SequenceForClip(const FString& ClipName) const
{
    const FSoftObjectPath* Path = SequenceIndex.Find(CleanName(ClipName));
    return Path != nullptr ? Cast<ULevelSequence>(Path->TryLoad()) : nullptr;
}

UAnimSequence* AMojuloGameMode::AnimForClip(const FString& ClipName) const
{
    // The clip's cleaned GLB name ('body:idle' -> 'body_idle'), else the one
    // asset whose name contains it: the name Interchange gives a glTF
    // animation is UNPINNED (import_mojulo.py's find_clip reads the same way).
    const FString Want = CleanName(ClipName);
    const FSoftObjectPath* Path = AnimIndex.Find(Want);
    if (Path == nullptr)
    {
        TArray<FString> Hits;
        for (const TPair<FString, FSoftObjectPath>& Entry : AnimIndex)
            if (Entry.Key.Contains(Want)) Hits.Add(Entry.Key);
        if (Hits.Num() == 1) Path = AnimIndex.Find(Hits[0]);
    }
    return Path != nullptr ? Cast<UAnimSequence>(Path->TryLoad()) : nullptr;
}

USkeletalMeshComponent* AMojuloGameMode::FindSkeletal(AActor* Root)
{
    // the skinned body under a figure's wrapper (one actor per GLB node, as
    // the rigid parts are); null for a rigid figure
    if (Root == nullptr) return nullptr;
    if (USkeletalMeshComponent* Mesh = Root->FindComponentByClass<USkeletalMeshComponent>()) return Mesh;
    TArray<AActor*> Children;
    Root->GetAttachedActors(Children);
    for (AActor* Child : Children)
        if (USkeletalMeshComponent* Mesh = FindSkeletal(Child)) return Mesh;
    return nullptr;
}

bool AMojuloGameMode::PlayFigureClip(AActor* Figure, const FString& ClipName, bool bLoop)
{
    USkeletalMeshComponent* Mesh = FindSkeletal(Figure);
    if (Mesh == nullptr) return false;
    UAnimSequence* Anim = AnimForClip(ClipName);
    if (Anim == nullptr)
    {
        UE_LOG(LogTemp, Warning, TEXT("[mojulo] no AnimSequence for clip '%s' on the skinned figure '%s'"), *ClipName, *Figure->GetName());
        return false;
    }
    Mesh->PlayAnimation(Anim, bLoop);
    return true;
}

ULevelSequencePlayer* AMojuloGameMode::PlayClip(const FString& ClipName, bool bLoop)
{
    ULevelSequence* Sequence = SequenceForClip(ClipName);
    if (Sequence == nullptr)
    {
        UE_LOG(LogTemp, Warning, TEXT("[mojulo] no LevelSequence for clip '%s'"), *ClipName);
        return nullptr;
    }
    FMovieSceneSequencePlaybackSettings Settings;
    if (bLoop) Settings.LoopCount.Value = -1;
    ALevelSequenceActor* OutActor = nullptr;
    ULevelSequencePlayer* Player = ULevelSequencePlayer::CreateLevelSequencePlayer(GetWorld(), Sequence, Settings, OutActor);
    if (OutActor != nullptr) SequenceActors.Add(OutActor);
    if (Player != nullptr) Player->Play();
    return Player;
}

void AMojuloGameMode::SetupLocomotion()
{
    BuildSequenceIndex();

    // Ambient entities: everything with an idle clip breathes instead of
    // standing as a statue. First-claimant figures only — a figure bakes
    // ONCE, later entities sharing it have no body of their own, and two
    // players on one sequence fight.
    TSet<FString> Claimed;
    // The player's FIGURE is claimed by the player — a second entity sharing
    // it must not play a competing idle on the one baked body (pinned by the
    // U3 dump: the ring's en_unit idled the player's own suit).
    for (const FMojuloEntity& Entity : Score.Entities)
        if (Entity.Id == Score.Player && !Entity.Figure.IsEmpty()) Claimed.Add(Entity.Figure);
    for (const FMojuloEntity& Entity : Score.Entities)
    {
        if (Entity.Id == Score.Player || Entity.IdleClip.IsEmpty()) continue;
        if (!Entity.Figure.IsEmpty())
        {
            if (Claimed.Contains(Entity.Figure)) continue;
            Claimed.Add(Entity.Figure);
        }
        AActor* Figure = FindActorByCleanName(!Entity.Figure.IsEmpty() ? Entity.Figure : TEXT("entity:") + Entity.Id);
        SetActorTreeMovable(Figure);
        if (Figure != nullptr) DebugFigures.Add(Figure);
        if (!PlayFigureClip(Figure, Entity.IdleClip, true)) PlayClip(Entity.IdleClip, true);
    }

    // The player's suit: visible, third person, following the walker —
    // "walk the arena AS the suit". Frame/facing composition is UNPINNED
    // until the U3 arena slice eyes it.
    const FMojuloEntity* PlayerEntity = Score.Entities.FindByPredicate(
        [this](const FMojuloEntity& E) { return E.Id == Score.Player; });
    if (PlayerEntity == nullptr) return;
    AActor* Seat = FindActorByCleanName(!PlayerEntity->Figure.IsEmpty() ? PlayerEntity->Figure : TEXT("entity:") + PlayerEntity->Id);
    if (Walker == nullptr || (PlayerEntity->IdleClip.IsEmpty() && PlayerEntity->WalkClip.IsEmpty()))
    {
        // First person: no travel clips — make sure the WHOLE seat body is
        // hidden (the import-time hide misses attached child actors) and
        // never collides with the pilot.
        SetActorTreeHidden(Seat, true);
        SetActorTreeCollision(Seat, false);
        return;
    }
    PlayerSuit = Seat;
    if (PlayerSuit == nullptr || Walker == nullptr) return;
    SetActorTreeMovable(PlayerSuit);
    SetActorTreeCollision(PlayerSuit, false);
    SetActorTreeHidden(PlayerSuit, false);
    SuitBaseQuat = PlayerSuit->GetActorQuat();
    BaseControlYaw = Walker->GetControlRotation().Yaw;
    // Frame the SUIT, not the pilot: bounds over the whole attachment tree
    // (one actor per GLB node), arm back ~2 suit-heights, camera raised to
    // the suit's chest line.
    FBox Bounds(ForceInit);
    TArray<AActor*> Tree;
    Tree.Add(PlayerSuit);
    for (int32 i = 0; i < Tree.Num(); i++)
    {
        FVector Origin = FVector::ZeroVector, Extent = FVector::ZeroVector;
        Tree[i]->GetActorBounds(false, Origin, Extent);
        if (!Extent.IsNearlyZero()) Bounds += FBox(Origin - Extent, Origin + Extent);
        TArray<AActor*> Children;
        Tree[i]->GetAttachedActors(Children);
        Tree.Append(Children);
    }
    const float SuitHeight = Bounds.IsValid ? (Bounds.Max.Z - Bounds.Min.Z) : Score.Eye * 100.f;
    Walker->SetCameraRig(FMath::Max(Score.Eye * 350.f, SuitHeight * 2.f), SuitHeight * 0.55f);
    // A skinned suit plays its clips on its mesh: idle, else walk (the walk
    // loops on when there is no idle to swap to); a rigid one through its
    // LevelSequences, the walk held paused until it moves.
    SuitSkeletal = FindSkeletal(PlayerSuit);
    if (SuitSkeletal != nullptr)
    {
        if (!PlayerEntity->IdleClip.IsEmpty()) SuitIdleAnim = AnimForClip(PlayerEntity->IdleClip);
        if (!PlayerEntity->WalkClip.IsEmpty()) SuitWalkAnim = AnimForClip(PlayerEntity->WalkClip);
        UAnimSequence* First = SuitIdleAnim != nullptr ? SuitIdleAnim : SuitWalkAnim;
        if (First != nullptr) SuitSkeletal->PlayAnimation(First, true);
        else SuitSkeletal = nullptr; // no AnimSequence by either name: the LevelSequences below
    }
    if (SuitSkeletal == nullptr)
    {
        if (!PlayerEntity->IdleClip.IsEmpty()) SuitIdlePlayer = PlayClip(PlayerEntity->IdleClip, true);
        if (!PlayerEntity->WalkClip.IsEmpty())
        {
            SuitWalkPlayer = PlayClip(PlayerEntity->WalkClip, true);
            if (SuitWalkPlayer != nullptr) SuitWalkPlayer->Pause();
        }
    }
}

void AMojuloGameMode::TickPlayerSuit()
{
    if (PlayerSuit == nullptr || Walker == nullptr) return;
    // Wrapper follow: sequences pose parts RELATIVE to the wrapper, so
    // moving/turning the wrapper carries the animated suit. Yaw is a delta
    // composed on the imported base quat (a raw rotator lays it face-down).
    const FVector Feet = Walker->GetActorLocation() - FVector(0.f, 0.f, Walker->GetSimpleCollisionHalfHeight());
    PlayerSuit->SetActorLocation(Feet);
    const float DeltaYaw = Walker->GetControlRotation().Yaw - BaseControlYaw;
    PlayerSuit->SetActorRotation(FQuat(FRotator(0.f, DeltaYaw, 0.f)) * SuitBaseQuat);

    const bool bMoving = Walker->GetVelocity().Size2D() > 60.f * EyeScale;
    if (bMoving == bSuitWalking) return;
    bSuitWalking = bMoving;
    if (SuitSkeletal != nullptr)
    {
        if (SuitIdleAnim != nullptr && SuitWalkAnim != nullptr) SuitSkeletal->PlayAnimation(bMoving ? SuitWalkAnim : SuitIdleAnim, true);
    }
    else if (SuitWalkPlayer != nullptr && SuitIdlePlayer != nullptr)
    {
        if (bMoving) { SuitIdlePlayer->Pause(); SuitWalkPlayer->Play(); }
        else { SuitWalkPlayer->Pause(); SuitIdlePlayer->Play(); }
    }
}

bool AMojuloGameMode::AttachDepiction(AMojuloMarker* Marker, const FString& Kind)
{
    FString Text;
    if (!FFileHelper::LoadFileToString(Text, *(FPaths::ProjectConfigDir() / TEXT("MojuloDepiction.json")))) return false;
    TSharedPtr<FJsonObject> Table;
    const TSharedRef<TJsonReader<>> Reader = TJsonReaderFactory<>::Create(Text);
    if (!FJsonSerializer::Deserialize(Reader, Table) || !Table.IsValid()) return false;
    FString Path;
    if (!Table->TryGetStringField(Kind, Path) || Path.IsEmpty()) return false;
    UNiagaraSystem* System = LoadObject<UNiagaraSystem>(nullptr, *Path);
    if (System == nullptr)
    {
        UE_LOG(LogTemp, Warning, TEXT("[mojulo] depiction missing: %s"), *Path);
        return false;
    }
    UNiagaraComponent* FX = NewObject<UNiagaraComponent>(Marker);
    FX->SetupAttachment(Marker->GetRootComponent());
    FX->SetUsingAbsoluteScale(true);
    FX->SetRelativeScale3D(FVector(0.25f));
    FX->SetAsset(System);
    FX->RegisterComponent();
    FX->Activate(true);
    UE_LOG(LogTemp, Display, TEXT("[mojulo] depiction=%s system=%s"), *Kind, *Path);
    return true;
}

void AMojuloGameMode::SpawnMechanicMarkers()
{
    UWorld* World = GetWorld();
    for (FMojuloPickup& Pickup : Score.Pickups)
    {
        AMojuloMarker* Marker = World->SpawnActor<AMojuloMarker>(Pickup.Pos + FVector(0.f, 0.f, 60.f * EyeScale), FRotator::ZeroRotator);
        const float S = 0.5f * EyeScale;
        Marker->SetShape(true, FVector(S), FLinearColor(0.98f, 0.85f, 0.25f));
        AttachDepiction(Marker, TEXT("pickup"));
        Pickup.Marker = Marker;
    }
    for (const FMojuloHazard& Hazard : Score.Hazards)
    {
        AMojuloMarker* Marker = World->SpawnActor<AMojuloMarker>(Hazard.Pos, FRotator::ZeroRotator);
        const float S = Hazard.Radius * 2.f / 100.f;
        Marker->SetShape(true, FVector(S), FLinearColor(0.95f, 0.25f, 0.2f));
        AttachDepiction(Marker, TEXT("hazard"));
    }
    for (const FMojuloZone& Exit : Score.Exits)
    {
        AMojuloMarker* Marker = World->SpawnActor<AMojuloMarker>(Exit.Pos, FRotator::ZeroRotator);
        Marker->SetShape(false, FVector(0.35f, 0.35f, 1.2f), FLinearColor(0.2f, 0.9f, 0.8f));
        if (!AttachDepiction(Marker, TEXT("exit"))) Marker->Destroy();
    }
}

void AMojuloGameMode::StartMusic()
{
    if (Score.Soundtrack.IsEmpty()) return;
    const FString Path = FString::Printf(TEXT("/Game/MojuloPack/Audio/%s.%s"), *Score.Soundtrack, *Score.Soundtrack);
    USoundWave* Wave = LoadObject<USoundWave>(nullptr, *Path);
    if (Wave != nullptr) UGameplayStatics::SpawnSound2D(this, Wave);
    else UE_LOG(LogTemp, Warning, TEXT("[mojulo] soundtrack asset missing: %s"), *Path);
}

float AMojuloGameMode::BodyDistance(const FVector& Target) const
{
    // Preserve the walker segment; foreign pawns use their collision body.
    const FVector Feet = PlayerFeet();
    const float Height = Walker != nullptr ? Walker->GetEyeMeters() * 100.f : PlayerPawn->GetSimpleCollisionHalfHeight() * 2.f;
    const float Z = FMath::Clamp(Target.Z, Feet.Z, Feet.Z + Height);
    return FVector::Dist(Target, FVector(Feet.X, Feet.Y, Z));
}

bool AMojuloGameMode::ZoneHit(const FMojuloZone& Zone, const FVector& Pos) const
{
    if (Zone.bHasHalf)
    {
        // Half extents are mojulo (x, y, z); UE y is negated mojulo y but
        // extents are unsigned — planar test is x/y, tall test adds z.
        if (FMath::Abs(Pos.X - Zone.Pos.X) > Zone.Half.X || FMath::Abs(Pos.Y - Zone.Pos.Y) > Zone.Half.Y) return false;
        return Zone.bPlanar || FMath::Abs(Pos.Z - Zone.Pos.Z) <= Zone.Half.Z;
    }
    if (Zone.bPlanar)
        return FVector2D(Pos.X - Zone.Pos.X, Pos.Y - Zone.Pos.Y).Size() <= Zone.Radius;
    return FVector::Dist(Pos, Zone.Pos) <= Zone.Radius;
}

void AMojuloGameMode::Tick(float DeltaSeconds)
{
    Super::Tick(DeltaSeconds);
    if (!bScoreLoaded) return;
    if (!IsValid(PlayerPawn) || PlayerPawn != UGameplayStatics::GetPlayerPawn(this, 0))
    {
        ConfigureWalker();
        if (!IsValid(PlayerPawn) || PlayerPawn != UGameplayStatics::GetPlayerPawn(this, 0)) return;
    }
    if (Walker == nullptr && PlayerPawn->GetActorLocation().Z < PlayerKillZ) ResetPlayer();

    if (bForeignAutoWalk && !bProbePressed && GetWorld()->GetTimeSeconds() >= 2.f)
    {
        if (APlayerController* PC = UGameplayStatics::GetPlayerController(this, 0))
        {
            // aim the probe at the seat's facing (the PlayerStart's yaw = the score's walk.yaw), level pitch
            PC->SetControlRotation(FRotator(0.f, PlayerSpawn.Rotator().Yaw, 0.f));
            PC->InputKey(FInputKeyEventArgs(nullptr, FInputDeviceId::CreateFromInternalId(0), EKeys::W, IE_Pressed, FPlatformTime::Cycles64()));
            bProbePressed = true;
            ProbeStart = PlayerPawn->GetActorLocation();
            const FString Cam = PC->PlayerCameraManager ? PC->PlayerCameraManager->GetCameraRotation().ToString() : FString(TEXT("-"));
            UE_LOG(LogTemp, Display, TEXT("[mojulo-probe] walk pressed: control=%s camera=%s pawn_yaw=%.1f"), *PC->GetControlRotation().ToString(), *Cam, PlayerPawn->GetActorRotation().Yaw);
        }
    }
    if (JumpAt >= 0.f && !bJumpReleased && GetWorld()->GetTimeSeconds() >= JumpAt)
    {
        if (APlayerController* PC = UGameplayStatics::GetPlayerController(this, 0))
        {
            if (!bJumpPressed)
            {
                PC->InputKey(FInputKeyEventArgs(nullptr, FInputDeviceId::CreateFromInternalId(0), EKeys::SpaceBar, IE_Pressed, FPlatformTime::Cycles64()));
                bJumpPressed = true;
                JumpFrom = PlayerPawn->GetActorLocation();
                UE_LOG(LogTemp, Display, TEXT("[mojulo-probe] jump pressed at (%.2f,%.2f,%.2f)"), JumpFrom.X, JumpFrom.Y, JumpFrom.Z);
            }
            else
            {
                PC->InputKey(FInputKeyEventArgs(nullptr, FInputDeviceId::CreateFromInternalId(0), EKeys::SpaceBar, IE_Released, FPlatformTime::Cycles64()));
                bJumpReleased = true;
            }
        }
    }
    TickPlayerSuit();

    if (ShotAt >= 0.f && !bShotTaken && GetWorld()->GetTimeSeconds() >= ShotAt)
    {
        bShotTaken = true;
        const FVector ProbeEnd = PlayerPawn->GetActorLocation();
        UE_LOG(LogTemp, Display, TEXT("[mojulo-probe] pawn_class=%s auto_walk=%d jump=%d displacement_cm=%.2f position=(%.2f,%.2f,%.2f)"),
            *PlayerPawn->GetClass()->GetPathName(), bForeignAutoWalk, bJumpPressed, FVector::Dist2D(ProbeStart, ProbeEnd), ProbeEnd.X, ProbeEnd.Y, ProbeEnd.Z);
        if (APlayerController* ProbePC = UGameplayStatics::GetPlayerController(this, 0))
        {
            const FString Cam = ProbePC->PlayerCameraManager ? ProbePC->PlayerCameraManager->GetCameraRotation().ToString() : FString(TEXT("-"));
            UE_LOG(LogTemp, Display, TEXT("[mojulo-probe] at shot: control=%s camera=%s"), *ProbePC->GetControlRotation().ToString(), *Cam);
        }
        if (bProbePressed)
        {
            if (APlayerController* PC = UGameplayStatics::GetPlayerController(this, 0))
                PC->InputKey(FInputKeyEventArgs(nullptr, FInputDeviceId::CreateFromInternalId(0), EKeys::W, IE_Released, FPlatformTime::Cycles64()));
        }
        if (APlayerController* ShotPC = UGameplayStatics::GetPlayerController(this, 0))
            ShotPC->ConsoleCommand(TEXT("HighResShot 1280x720"));
        auto Dump = [](const TCHAR* Tag, AActor* Figure)
        {
            if (Figure == nullptr) return;
            TArray<AActor*> Children;
            Figure->GetAttachedActors(Children);
            const FVector Part = Children.Num() ? Children[0]->GetActorLocation() : FVector::ZeroVector;
            UE_LOG(LogTemp, Display, TEXT("[mojulo-dump] %s %s wrapper=(%.0f,%.0f,%.0f) part0=(%.0f,%.0f,%.0f) kids=%d"),
                Tag, *Figure->GetName(), Figure->GetActorLocation().X, Figure->GetActorLocation().Y, Figure->GetActorLocation().Z,
                Part.X, Part.Y, Part.Z, Children.Num());
        };
        for (AActor* Figure : DebugFigures) Dump(TEXT("ambient"), Figure);
        Dump(TEXT("player"), PlayerSuit);
        if (Walker != nullptr)
            UE_LOG(LogTemp, Display, TEXT("[mojulo-dump] walker=(%.0f,%.0f,%.0f)"),
                Walker->GetActorLocation().X, Walker->GetActorLocation().Y, Walker->GetActorLocation().Z);
    }

    const float Now = GetWorld()->GetTimeSeconds();
    if (PendingMenuAt >= 0.f && Now >= PendingMenuAt) { ToMenu(); return; }
    if (PendingResetAt >= 0.f && Now >= PendingResetAt) { PendingResetAt = -1.f; ResetLevel(); }
    if (State != TEXT("playing")) return;

    APlayerController* PC = UGameplayStatics::GetPlayerController(this, 0);
    if (PC != nullptr && PC->WasInputKeyJustPressed(EKeys::M) && MojuloScore::HasMenuMap()) { ToMenu(); return; }

    const FVector Pos = PlayerFeet();
    for (const FMojuloZone& Zone : Score.Exits)
        if (ZoneHit(Zone, Pos)) { Complete(); return; }

    if (SurviveLeft >= 0.f)
    {
        SurviveLeft = FMath::Max(0.f, SurviveLeft - DeltaSeconds);
        if (SurviveLeft == 0.f) { Complete(); return; }
    }

    for (FMojuloPickup& Pickup : Score.Pickups)
        if (!Pickup.bTaken && BodyDistance(Pickup.Pos) <= Pickup.Radius + 40.f * EyeScale)
        {
            Pickup.bTaken = true;
            if (Pickup.Marker != nullptr) Pickup.Marker->SetActorHiddenInGame(true);
            Bag.FindOrAdd(Pickup.Item) += 1;
            UE_LOG(LogTemp, Display, TEXT("moj: picked up %s"), *Pickup.Item);
        }

    for (FMojuloHazard& Hazard : Score.Hazards)
    {
        Hazard.Cool = FMath::Max(0.f, Hazard.Cool - DeltaSeconds);
        if (Hazard.Cool == 0.f && BodyDistance(Hazard.Pos) <= Hazard.Radius + 40.f * EyeScale)
        {
            Hazard.Cool = 0.8f; // the Unity kernel's HazardCooldown
            Hp = FMath::Max(0.f, Hp - Hazard.Damage);
            UE_LOG(LogTemp, Display, TEXT("moj: hazard hit, hp %d"), (int32)Hp);
            if (Score.bFailOnDeath && Hp <= 0.f) { Fail(); return; }
        }
    }
}

void AMojuloGameMode::Complete()
{
    State = TEXT("complete");
    Banner = TEXT("LEVEL COMPLETE");
    UE_LOG(LogTemp, Display, TEXT("moj: level complete"));
    MojuloScore::MarkCompleted(LevelRef);
    if (MojuloScore::HasMenuMap()) PendingMenuAt = GetWorld()->GetTimeSeconds() + 1.5f;
}

void AMojuloGameMode::Fail()
{
    State = TEXT("failed");
    Banner = TEXT("FAILED");
    UE_LOG(LogTemp, Display, TEXT("moj: level failed"));
    if (MojuloScore::HasMenuMap()) PendingMenuAt = GetWorld()->GetTimeSeconds() + 1.5f;
    else PendingResetAt = GetWorld()->GetTimeSeconds() + 1.5f;
}

void AMojuloGameMode::ResetLevel()
{
    Banner.Empty();
    Hp = Score.bHasHp ? Score.StartHp : -1.f;
    Bag.Empty();
    for (FMojuloPickup& Pickup : Score.Pickups)
    {
        Pickup.bTaken = false;
        if (Pickup.Marker != nullptr) Pickup.Marker->SetActorHiddenInGame(false);
    }
    SurviveLeft = Score.SurviveSeconds;
    ResetPlayer();
    State = TEXT("playing");
}

void AMojuloGameMode::ToMenu()
{
    UGameplayStatics::OpenLevel(this, FName(*MojuloScore::MapPath(TEXT("mojulo-menu"))));
}
